GimCorpus.put(417,0,[[1,24,"וצריך לבדוק כן אחר השחיטה וכו'. א\"א כבר הסכימו חכמינו שאינו צריך אא\"כ רוצה לשחוט אחריה שלא אמרו בגמרא צריך לבדוק אלא השוחט ונמצאת פגומה ואילו היה צריך היו אומרים כן כמו שאמרו השוחט צריך שיבדוק בסימנין אחר ששחט:",1,0],[3,4,"וכן אם שהה כדי שיגביהנה וירביצנה וכו'. א\"א זו הסברא לא טובה היא ולא נכונה ומפירוש משובש הביאה והלא אמרו במשנה אם שהה כדי שחיטה אחרת ומיעוט שחיטה לא נכנסה בזה הספק ועוד היה לו לומר כדי מיעוט שחיטה ועוד שאין זה הפירוש מתנהג בהחליד במיעוט סימנים אבל הפירוש השוה לשניהם ששחט הרוב ושהה וגמר מי אמרינן כיון דגמר שהייה בשחיטה היא מאן מוכח או דילמא לא חיישינן להכי ובחצי קנה דעוף ליכא למיחש כלל וכל שכן לרוב ונראה לי באותן שתי הבעיות תיקו ולקולא:",1,0],[3,24,"ניקבה הגרגרת נקב מפולש משני צדדיה. א\"א זה פירוש משובש ופירש אותו על נפחתה:",1,0],[6,8,"קני הכבד והן המזרקין שבו שבהן הדם. א\"א כמדומה לי שהוא סובר על הנקבים [ס\"א הקנים] דכבדא כריאה שאפילו על מה שיש מהם בתוך הכבד נאמר שאם ניקב במשהו טריפה ואינו כן ואין חכם שיסבור כן אלא מה שנתפשט ממנו לריאה והוא חוץ לכבד ועל כן אינו חשש נקב בכבד בשביל נקב עצמו אלא שמא דרך הושט בא לו לכבד:",1,0],[6,8,"והיה הקצה החד שלה בפנים בידוע שניקבה. א\"א אין בכאן תבלין ולא מלח והמבין יבין ואין כאן ודאי נקובה:",2,0],[6,12,"מחט שנמצאת בעובי בית הכוסות כשרה ואם ניקבה נקב מפולש. א\"א אין זה מיושר:",1,0],[6,12,"ונמצאת טיפת דם במקום הנקב. כתב הראב\"ד ז\"ל הטיפה צריכה שתמצא מבחוץ:",2,0],[6,13,"ואם היה ספק נוקב ספק לא נוקב. א\"א קשה בדיקת הדקין:",1,0],[7,4,"במה דברים אמורים כשסתם מקום הנקב שבאונות בשר. א\"א הנה הוא סובר דוקא סריך אבל לא סריך לאו ודוקא בבשרא אבל בגרמא לחודיה לא ויש מן הגאונים שאמרו בין סריך בין לא סריך בין בבשרא בין בגרמא ואני אומר בשניקבה ודאי בעינן סריך דוקא ובבשרא דוקא שאין סירכא סותמת ואין עצם סותם ועל שמעתיה דרב נחמן הוא דאתמר דקאמר ניקבה אבל כל סירכא מאונא לדופן כשרה מפני דוחק רביצתה עליו נעשו הסרכות ולא משום נקב וכן עיקר. עכ\"ל:",1,0],[7,5,"אם נמצאת נקובה ונמצאת בדופן מכה במקום הנקב תולין. א\"א זה העיקר טעות גדולה שאם נמצאת נקובה אין להכשיר במכת הדופן באומד אלא כך אמרו שאם יש מכה בדופן ונפחו את הריאה ועלתה בנפיחה תולין את הדיבוק במכת הדופן ואם אין שם מכה אע\"פ שעלתה בנפיחה לא כלום הוא שאני אומר שהדבוק מחמת נקב היה וקרום עלה עליו:",1,0],[7,8,"זה עיקר גדול יהיה בידך וכו'. א\"א זה המחבר שונה רב נחמיה דבדיק לה בפושרין לקולא ורוב המפרשים אומרים לחומרא דאע\"ג דאיכא מכה בדופן בדיק לה. עכ\"ל:",1,0],[7,14,"מחט שנמצאת בריאה נופחין אותה. א\"א וכיון שנמצא המחט הרי נחתכה הריאה ואין נופחין אותה עוד אלא שאם נפחו אותה קודם שנחתכה הריאה ועלתה בנפיחה כשרה:",1,0],[7,16,"נשתנה למראה האסור אפילו כל שהוא טרפה. א\"א אומר אני כל מקום שהזכירו פסול בריאה ולא הזכירו בה מקצתה עד דהויא בכולה שכיון שהזכירו במקצת דוקא הוא והרי האדימה שהיו מחולקין בה בפירוש ולבסוף הכשירוהו כולה הילכך חזותא שהכשירו אפילו היו בה מראות הרעות כשרה. עכ\"ל:",1,0],[7,21,"כל עוף שנמצאת הכבד שלו כמראה בני מעים. א\"א זה כתב במקום הוריקה כנגד בני מעים וטעה בפירושו אלא כך שאל הוריקו סמוך לבני מעים מהו תלינן ליה דבצד בני מעים אתיא לה ירקות או לא ופשט לה דאפילו לבני מעיים גופייהו איכא למיחש אלא שאינו ניכר בהם. עכ\"ל:",1,0],[8,14,"ומנין גידים אלו בעוף ששה עשר גידין תחלתן מן העצם של מטה. א\"א זה חדוש גדול שלא שמעתי כמותו ומעולם לא בדקתי צומת הגידים אלא מן הארכובה ולמעלה כנגד צומות הגידין של בהמה ואמת הוא שהם יורדים עד למטה עד שהם מתקשרים ומתחזקים בארכובה משם הם חיים ומפרנסים את הגוף:",1,0],[8,17,"וכבר ביארנו שהבהמה וכו'. א\"א זאת האומנות לא עלתה לו כהוגן בכאן שיחשב חתוכת הגידים כנטולה ומה בין חתוכה לפסוקה והוא סבור שניטל צומת הגידין הוא שנחתכו ולפיכך מנה אותן בנטולה ולא דקדק יפה אלא אם רצה למנותה בנטולין יאמר שאם לא נחתכו אלא שנעקרו מן הארכובה ונקפלו מעל העצם עד למעלה טריפה ולפיכך אמר וכן שניטל צומת הגידין ולא אמר שנחתך. שמעה עמי בינה זאת. עכ\"ל:",1,0],[9,8,"באי זה איברים אמרו באיברים שבחלל הגוף. א\"א אומר אני בכל אבר שאם נשבר תהיה בו טרפה אפילו נתרסק אבר מן האיברים שאם ניטלו כשרין. עכ\"ל:",1,0],[9,17,"כגון טחול וכליות. א\"א זה ספק:",1,0],[10,3,"בהמה שנשמט הירך שלה וכו'. א\"א דומה שהוא סובר היינו בוקא דאטמא דשף מדוכתיה ולא כלום הוא אלא שבעצם נאמרו שניהם והוא הכף עצמו שנשמט ראשו העליון מן השדרה וזהו שמוטת ירך אבל בוקא דאטמא הוא הראש התחתון שנשמט מן הקולית הוא כעין בוקא ונכנס למכתשת שבכף וזהו בוקא דאטמא דשף מדוכתיה והוא דאיעכול ניביה אבל השמוטה שאמרנו אין צורך עכול עכ\"ל:",1,0],[10,11,"ואלו הן עוף שנשתנו מראה בני מעיו. א\"א אין זה מחוור שי\"ל לא מנו אותה בבהמה משום דלא שכיחא שכשיגיע החום לבני מעיה לחמם אותם כבר היא מתה מפני שחמימותה מרובה משל עוף ויש מקצת ראיה בגמרא:",1,0],[11,5,"וכן אם נמצא בה אבעבוע כו'. א\"א ברוב דברים לא יחדל פשע ואם ניקב סימפון שתחתיו מה בכך והלא לא אמרו אלא סמפון שניקב לחבירו טרפה:",1,0],[11,7,"ואע\"פ שאלו הן הדברים וכו'. א\"א אינן נראין והרי הוא חוזר ממה שאמר למעלה:",1,0],[11,9,"אפילו במקום רביצתה או על הסדר שלא במקום רביצתה אוסרין אותה. א\"א זהו אומא לאונא ואין שומעין לו שהגדולים מהגאונים התירוה:",1,0],[11,10,"ומיעוט מקומות מתירין אותה וכו'. א\"א אני מתיר וכבר כתבתי למעלה מה שראוי לסמוך עליו:",1,0],[11,13,"ואין אומרים שמא נקובה היתה או שמא דבוקה. א\"א יש שחולקין על הריאה:",1,0],[12,15,"אבל אם היה ריוח ביום אינו צריך להודיעו. א\"א מעולם לא הפליג בריוח אותו היום אלא בערב הערב יש מי שמקדים שני ימים ושוחט ובא רבי יהודה לומר אף על פי שיש מקדימין אינו צריך להודיעו וכן מוכח בתוספתא:",1,0],[14,8,"דם הניתז ושעל גבי הסכין וכו'. א\"א אלו דברי הרב ז\"ל שעושה דברי רבי יהודה מפרש משום דאמר אימתי אבל אין אחרים מודים לו משום דגמרא מפרש להו דפליגי בקראי:",1,0]]);
